// International parcel rates. Prices are in cents: a flat price covers the first kilo,
// then each started 100 g is charged. Above 2 kg the weight is first rounded up to the next 0.5 kg.
const ZONES = {
  EU: { firstKiloCents: 1500, per100gCents: 80 },
  WORLD: { firstKiloCents: 2500, per100gCents: 140 },
};

export class RestrictedItemError extends Error {
  constructor(message = "lithium batteries cannot ship internationally") {
    super(message);
    this.name = "RestrictedItemError";
  }
}

export function internationalQuote(weightKg, zone, items = []) {
  if (!(weightKg > 0)) throw new RangeError("weight must be positive");
  if (!Object.hasOwn(ZONES, zone)) throw new RangeError(`unknown zone: ${zone}`);
  if (items.some((item) => item?.lithium === true)) throw new RestrictedItemError();

  // Work in whole grams so decimal weights like 1.1 kg don't pick up float error.
  let grams = Math.round(weightKg * 1000);
  if (grams > 2000) grams = Math.ceil(grams / 500) * 500;

  const { firstKiloCents, per100gCents } = ZONES[zone];
  return firstKiloCents + Math.ceil(Math.max(0, grams - 1000) / 100) * per100gCents;
}
EOF
