import { test } from "node:test";
import assert from "node:assert/strict";
import { internationalQuote, RestrictedItemError } from "../src/international.js";

test("first kilo is the flat price", () => {
  assert.equal(internationalQuote(0.3, "EU", []), 1500);
  assert.equal(internationalQuote(1, "WORLD", []), 2500);
});
test("each started 100 g after the first kilo is charged", () => {
  assert.equal(internationalQuote(1.1, "EU", []), 1580);
  assert.equal(internationalQuote(1.15, "EU", []), 1660);
  assert.equal(internationalQuote(2, "WORLD", []), 2500 + 10 * 140);
});
test("above 2 kg the weight rounds up to the next 0.5 kg", () => {
  assert.equal(internationalQuote(2.1, "EU", []), 1500 + 15 * 80);
  assert.equal(internationalQuote(2.5, "EU", []), 1500 + 15 * 80);
  assert.equal(internationalQuote(2.51, "WORLD", []), 2500 + 20 * 140);
});
test("lithium items are refused", () => {
  assert.throws(() => internationalQuote(1, "EU", [{ lithium: true }]), RestrictedItemError);
  assert.equal(internationalQuote(1, "EU", [{ lithium: false }]), 1500);
});
test("bad zone or weight is rejected", () => {
  assert.throws(() => internationalQuote(1, "MARS", []), RangeError);
  assert.throws(() => internationalQuote(0, "EU", []), RangeError);
});
EOF
